use std::{fs,path::Path,collections::BTreeMap};
fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let data=fs::read_to_string(p.join("DESCENT.tsv")).unwrap();let mut groups:BTreeMap<(usize,usize),(usize,usize,usize,usize,usize)>=BTreeMap::new();let(mut calls,mut yes,mut no,mut pre,mut refyes,mut cap,mut multi)=(0,0,0,0,0,0,0);for l in data.lines().skip(1){let v:Vec<_>=l.split('\t').collect();let g:usize=v[0].parse().unwrap();let h:usize=v[4].parse().unwrap();let a=groups.entry((g,h)).or_default();a.0+=1;calls+=1;match v[5]{"component"=>{a.1+=1;yes+=1;if v[12].parse::<usize>().unwrap()>1{multi+=1}},"no_component"=>{a.2+=1;no+=1},"precondition"=>{a.3+=1;pre+=1},_=>panic!()};if v[17]=="true"{a.4+=1}else{cap+=1}if v[13]=="true"{refyes+=1}}
let mut out=String::from("g\tH\tpolicies\tprojected_components\tno_component\tprecondition\tanchor_ref_completed\n");for((g,h),(n,y,no,pre,a))in groups{out+=&format!("{g}\t{h}\t{n}\t{y}\t{no}\t{pre}\t{a}\n");}fs::write(p.join("DESCENT-SUMMARY.tsv"),&out).unwrap();print!("{out}");let totals=format!("policies={calls}\nprojected_components={yes}\nno_component={no}\nprecondition={pre}\nunrestricted_ref_completed={refyes}\nanchor_ref_capped={cap}\nselected_multifibre_witnesses={multi}\n");print!("{totals}");fs::write(p.join("DESCENT-TOTALS.txt"),totals).unwrap();
let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='1050' height='490'><rect width='1050' height='490' fill='white'/><g font-family='Arial' fill='#173544'><text x='35' y='35' font-size='22'>Projected pencil descent: retained policy outcomes</text><text x='35' y='63' font-size='14'>Each bar contains two targets. Prefix anchors; size rule matches Compact, membership does not.</text>");for (panel,g)in[2usize,3,4].iter().enumerate(){let lines:Vec<_>=out.lines().skip(1).filter(|l|l.split('\t').next().unwrap().parse::<usize>().unwrap()==*g).collect();let ox=65.+panel as f64*335.;svg+=&format!("<text x='{ox}' y='112' font-size='18'>Genus {g}</text><path d='M {ox} 340 h 280' stroke='#526673'/>");for(j,line)in lines.iter().enumerate(){let v:Vec<usize>=line.split('\t').map(|s|s.parse().unwrap()).collect();let x=ox+15.+j as f64*65.;let mut yy=340.;for (count,color)in[(v[3],"#287f80"),(v[4],"#bac6cb"),(v[5],"#bd773c")]{let height=count as f64*90.;yy-=height;svg+=&format!("<rect x='{x}' y='{yy}' width='39' height='{height}' fill='{color}'/>");}svg+=&format!("<text x='{x}' y='367' font-size='14'>{}</text>",v[1]);}svg+=&format!("<text x='{ox}' y='397' font-size='14'>H: actual anchor count</text>");}for(i,(name,color))in[("projected decomposition","#287f80"),("no component","#bac6cb"),("precondition failure","#bd773c")].iter().enumerate(){let x=35+i*320;svg+=&format!("<rect x='{x}' y='423' width='17' height='17' fill='{color}'/><text x='{}' y='437' font-size='14'>{name}</text>",x+25);}svg+="<text x='35' y='471' font-size='13'>hec_fibre_pencil_20261116 / projected descent / exact fixed counts; no elapsed-time measurement.</text></g></svg>";fs::write(p.join("DESCENT-COUNTS.svg"),svg).unwrap();}
